/* =====================================================================
   story-hires2.js : séquences d'embauche LONGUES, lot 2 (v9) — textes ORIGINAUX écrits pour Miqka City
   (aucune réplique reprise des œuvres d'origine). Chiaki, Rin, Topaz, Bakool Ja Ja, Zenos, Aventurine, Fandaniel, Sinbad.
   Mêmes conventions que story-hires.js : perso à GAUCHE, Miqka à DROITE, {ville} = nom choisi par le joueur.
   Sprites et fonds chargés uniquement à l'ouverture de la séquence (préchargement moteur), donc jamais avant l'embauche.
   Crédits des images : SOURCES.md et Réglages › Crédits.
   ===================================================================== */
(function(){
"use strict";
const ST = window.STORY; if(!ST) return;
const C = ST.characters, B = ST.backgrounds;
/* h = hauteur relative ; ax = ancrage horizontal ; lift = buste remonté au-dessus de la boîte (portrait) ;
   lh / ly = hauteur et remontée (en %) propres au mode paysage */
const S2 = "assets/chars/";
C.chiaki     = {name:"Chiaki", poses:{
  neutre:{src:S2+"chiaki_neutre.webp", h:.66, ax:.5, lift:1, lh:.78, ly:0},
  pense:{src:S2+"chiaki_pense.webp", h:.66, ax:.5, lift:1, lh:.78, ly:0},
  dodo:{src:S2+"chiaki_dodo.webp", h:.66, ax:.5, lift:1, lh:.78, ly:0},
  serieuse:{src:S2+"chiaki_serieuse.webp", h:.66, ax:.5, lift:1, lh:.78, ly:0}}};
C.rin        = {name:"Rin",        poses:{neutre:{src:S2+"rin.webp", h:1.02, ax:.5, lh:.98}}};
C.topaz      = {name:"Topaz",      poses:{neutre:{src:S2+"topaz.webp", h:.98, ax:.36, lh:.96}}};
C.bakool     = {name:"Bakool Ja Ja", poses:{neutre:{src:S2+"bakool.webp", h:1.06, ax:.5, lh:1}}};
C.zenos      = {name:"Zenos",      poses:{neutre:{src:S2+"zenos.webp", h:1.12, ax:.62, lh:1}}};
C.aventurine = {name:"Aventurine", poses:{neutre:{src:S2+"aventurine.webp", h:1.02, ax:.5, lh:.98}}};
C.fandaniel  = {name:"Fandaniel",  poses:{neutre:{src:S2+"fandaniel.webp", h:1.02, ax:.5, lh:.98}}};
C.sinbad     = {name:"Sinbad",     poses:{neutre:{src:S2+"sinbad.webp", h:1.02, ax:.45, lh:.98}}};
["chiaki","rin","topaz","bakool","zenos","aventurine","fandaniel","sinbad"].forEach(id=>{ const ps=C[id].poses; if(!ps.buste) ps.buste=ps.neutre; });
Object.assign(B, {
  arcade:"assets/bg/arcade.webp", stade:"assets/bg/stade.webp", vestiaire:"assets/bg/vestiaire.webp", bureau:"assets/bg/bureau.webp",
  ruines:"assets/bg/ruines.webp", jungle:"assets/bg/jungle.webp", arene:"assets/bg/arene.webp", trone:"assets/bg/trone.webp",
  casino:"assets/bg/casino.webp", strip:"assets/bg/strip.webp", feux:"assets/bg/feux.webp", port:"assets/bg/port.webp",
  theatre:"assets/bg/theatre.webp", marche:"assets/bg/marche.webp"
});
const X = (o, e) => Object.assign(o, e || {});
const M = (pose, text, e) => X({speaker:"miqka", pose, text}, e);
const P = id => (pose, text, e) => X({speaker:id, pose, text}, e);
const N = (text, e) => X({text}, e);
const BJ = P("bigjim"), ES = P("estinien"), HO = P("homer"), HK = P("hancock");

/* ---------------- CHIAKI — JOUEUSE ---------------- */
ST.scenes.hire_chiaki = { duo:true, chapter:"Embauche", title:"Chiaki — Joueuse", background:"grandrue", lines:[
  N("{ville}, un mardi. Big Jim a installé un compteur de passages sur la grand-rue. Il affiche « 3 ». Dont deux fois Homer.", {right:"shy"}),
  M("shy", "On a un adjoint, un garde, un responsable des donuts… mais personne pour s'amuser. Une ville sans loisirs, c'est une prison avec des bancs."),
  M("pointing", "Et je sais de quoi je parle. Soixante-sept ans, ça m'a laissé le temps d'étudier la question."),
  N("Au bout de la rue, une vieille salle d'arcade fermée depuis des années. La porte est entrouverte. Un bip-bip s'en échappe."),
  M("idea", "Quelqu'un joue là-dedans ? À dix heures du matin ? C'est soit un cambrioleur, soit une passionnée."),
  N("Les néons grésillent. Une seule borne est allumée. Devant, une fille en sweat à capuche, endormie, la manette dans les mains.", {card:"La salle d'arcade…", bg:"arcade"}),
  P("chiaki")("dodo", "… zzz… encore une vague… zzz…", {effect:"nod"}),
  M("sweet", "Euh… bonjour ? Mademoiselle ? Votre partie continue toute seule."),
  P("chiaki")("neutre", "Hm ? Ah. Bonjour. Ce n'est pas grave. À ce niveau-là, je peux jouer en dormant… je crois."),
  M("excited", "Vous jouez en DORMANT ?! Et vous êtes à quel niveau ?", {effect:"hop"}),
  P("chiaki")("neutre", "Deux cent cinquante-cinq. Après, le jeu plante. Ça veut dire qu'on l'a fini. Enfin, moi je trouve."),
  M("idea", "Je suis Miqka, la maire de {ville}. Et vous êtes… ?"),
  P("chiaki")("neutre", "Chiaki Nanami. J'aime les jeux vidéo. Tous les jeux. C'est à peu près tout, je pense."),
  P("chiaki")("pense", "{ville}… Ça sonne comme un mot de passe. Ou le nom d'un boss secret qu'on débloque à la fin."),
  M("shy", "C'est le nom de la ville ! Un nom de ville tout à fait normal !"),
  P("chiaki")("neutre", "Ah. Pardon. Il me plaît bien, en fait. C'est facile à taper avec une manette."),
  M("excited", "Chiaki ! Est-ce que vous voulez travailler pour {ville} ? On n'a pas de loisirs, et vous êtes la personne la plus passionnée que j'ai vue cette semaine !"),
  P("chiaki")("pense", "Travailler… Il y a combien de PV, ce travail ?"),
  M("shy", "De… PV ? Il n'y a pas de points de vie dans un emploi municipal !"),
  P("chiaki")("neutre", "Il y en a toujours. Simplement, personne ne les affiche. C'est un mauvais design, je trouve."),
  N("Chiaki tend une deuxième manette à Miqka, sans quitter l'écran des yeux."),
  P("chiaki")("neutre", "Fais une partie avec moi. On apprend beaucoup de quelqu'un en jouant à deux. C'est ça, mon entretien d'embauche."),
  M("pointing", "C'est MOI qui fais passer l'entretien, normalement !", {effect:"shake"}),
  P("chiaki")("neutre", "Normalement. Mais tu as déjà pris la manette. Joueur deux, prêt."),
  N("Trois heures passent. Personne ne s'en rend compte.", {card:"Trois heures plus tard…", bg:"arcade"}),
  M("excited", "À gauche ! À GAUCHE ! Il y a un vaisseau à gauche !", {scr:"shake", effect:"bounce"}),
  P("chiaki")("neutre", "Je sais. Il est là depuis quatre secondes. Je le laisse vivre. Il a une famille, peut-être."),
  M("shy", "Ce sont des pixels !"),
  P("chiaki")("pense", "Les pixels ont le droit d'avoir une famille. Bon, j'appuie."),
  N("Bip. Boum. Le vaisseau explose. Le score de Chiaki dépasse l'affichage et revient à zéro."),
  M("idea", "Comment vous faites pour voir tout ça ? Moi, je vois surtout des couleurs qui crient."),
  P("chiaki")("neutre", "On regarde les motifs. Tout se répète, dans les jeux. Et en vrai aussi, un peu."),
  P("chiaki")("pense", "Par exemple, toi. Tu regardes la porte toutes les quatre minutes. Comme quelqu'un qui a l'habitude d'être surveillé."),
  M("shy", "Hein ?! N-non ! Pas du tout ! Je regarde… l'architecture !", {effect:"shake"}),
  P("chiaki")("neutre", "D'accord. Tu n'es pas obligée de me le dire. Mais si un jour tu veux, je suis bonne en déduction, je crois."),
  M("shy", "… Soixante-sept ans de prison. Pour un Crousty. Voilà. C'est dit."),
  P("chiaki")("pense", "Un Crousty… Hm. Il faut reconstituer les faits. Où était le Crousty ? Qui l'a vu en dernier ? Qui avait faim ?"),
  M("pointing", "MOI ! C'est moi qui avais faim ! Il n'y a pas de mystère !", {effect:"shake"}),
  P("chiaki")("neutre", "Il y a toujours un mystère. Mais je respecte tes aveux. C'est très honnête, comme stratégie."),
  N("La porte de l'arcade s'ouvre en grinçant. Une silhouette ronde s'avance, attirée par le bruit.", {left:"homer:calme"}),
  HO("calme", "J'ai entendu des bips. Les bips, c'est soit un jeu vidéo, soit le four à donuts. Les deux me conviennent."),
  P("chiaki")("neutre", "Bonjour. Tu veux jouer ? Il reste une manette. Elle colle un peu."),
  HO("joie", "Elle colle parce que c'est la mienne ! Je l'ai cachée ici en 1993 ! Enfin, une autre, mais l'idée est là.", {effect:"squish"}),
  M("sweet", "Homer, je vous présente Chiaki. Elle va peut-être s'occuper des loisirs de {ville}."),
  HO("calme", "Des loisirs ? À {ville} ? Le seul loisir ici, c'est de regarder Estinien sauter du toit de la mairie."),
  P("chiaki")("pense", "Quelqu'un saute du toit de la mairie ? Volontairement ? Je veux voir ça. C'est une mécanique intéressante."),
  N("Plus tard, sur la grand-rue. Big Jim attend devant l'arcade avec un carnet à souches.", {card:"Plus tard, devant l'arcade…", bg:"grandrue", left:"bigjim:neutre"}),
  BJ("neutre", "Madame la maire. Une salle de jeux, c'est une activité commerciale. Une activité commerciale, c'est une taxe. Pour le bien de la ville.", {effect:"nod"}),
  M("pointing", "Big Jim ! On n'a même pas encore ouvert !"),
  BJ("neutre", "Justement. La taxe d'avant l'ouverture est la plus douce. Après, elle a des dents."),
  P("chiaki")("neutre", "Monsieur. Si je bats votre score à n'importe quel jeu, la taxe disparaît ?"),
  BJ("neutre", "Jeune fille, j'ai été champion de bowling du comté trois années de suite. Pas d'arcade. De bowling."),
  P("chiaki")("neutre", "Le bowling, c'est un jeu. J'aime tous les jeux. Donc ça marche, je pense."),
  N("Un quart d'heure plus tard, Big Jim regarde une quille rouler très lentement vers une flaque. Chiaki, elle, a fait strike en bâillant."),
  BJ("neutre", "… Exonération pour la première année. Pour le bien de la ville. Et parce que je n'ai pas vu de témoins.", {effect:"nod"}),
  M("excited", "Chiaki ! Vous l'avez battu ! Au bowling ! Avec un ballon de foot dégonflé !", {effect:"bounce"}),
  P("chiaki")("dodo", "C'était le seul ballon… zzz… Pardon. La victoire me fatigue toujours un peu."),
  N("Le soir tombe. Une voix chantante s'élève derrière une pile de cartons.", {left:"hancock:buste"}),
  HK("buste", "Bonsoir, bonsoir ! Codes de triche ! Vies infinies, Kwak Coin infinis, et même un code pour annuler une peine de prison ! 15 Kwak Coin le code ^^", {effect:"squish"}),
  M("excited", "Un code pour annuler une peine de prison ?! Je le prends ! Je le prends deux fois !", {effect:"hop"}),
  P("chiaki")("serieuse", "Miqka. Non."),
  M("shy", "M-mais… soixante-sept ans, Chiaki ! Ce serait juste un tout petit raccourci !"),
  P("chiaki")("serieuse", "Tricher, ça gâche le jeu. Même quand le jeu est difficile. Surtout quand il est difficile."),
  P("chiaki")("pense", "Et puis… ce code, il l'a déjà vendu à Homer ce matin. Homer a essayé. Il est resté coincé dans la porte du frigo."),
  HK("buste", "C'est un code en version bêta ! Les bugs sont offerts !", {effect:"bounce"}),
  M("pointing", "Hancock ! Vous vendez des bugs maintenant ?!", {effect:"shake"}),
  HK("buste", "Je vends ce que les gens achètent. Bonne soirée !"),
  N("Hancock s'éclipse. Miqka reste plantée là, les poings serrés. Chiaki ne dit rien un moment.", {left:"chiaki:neutre"}),
  M("shy", "… Vous avez raison. Désolée. Parfois j'ai juste envie de sauter jusqu'au générique de fin."),
  P("chiaki")("neutre", "C'est normal. Moi aussi, quand un niveau est trop long. Mais le générique, c'est la partie la moins intéressante."),
  P("chiaki")("pense", "Le meilleur moment, c'est quand on rate, qu'on recommence, et qu'on comprend un peu mieux à chaque fois. Enfin, je crois."),
  M("sweet", "Chiaki… Vous voulez bien rester ? Pour organiser les loisirs ? Et pour… m'empêcher de tricher ?"),
  P("chiaki")("neutre", "D'accord. À une condition : la salle d'arcade reste ouverte la nuit. Et il y a un coussin. Un gros."),
  M("excited", "Marché conclu ! Bienvenue à {ville}, Chiaki !", {effect:"bounce"}),
  P("chiaki")("neutre", "Merci. Je pense que ça va être amusant. Joueur deux… tu veux une revanche ?"),
  M("excited", "Oui ! Et cette fois, je laisse vivre le vaisseau à gauche !"),
  N("Cette nuit-là, la borne de l'arcade affiche un nouveau record : « MIQKA — 120 points ». Juste en dessous de « CHIAKI — 9 999 999 ». Miqka le prend en photo quand même."),
  {end:true}
]};

/* ---------------- RIN — ATTAQUANTE ---------------- */
ST.scenes.hire_rin = { duo:true, chapter:"Embauche", title:"Rin — Attaquant", background:"arcade", lines:[
  N("À l'arcade, Chiaki a punaisé une affiche : « Grand match amical : {ville} contre Bourg-Voisin. Dimanche. »", {right:"excited"}),
  M("excited", "Un vrai match de foot ! Avec un vrai public ! Enfin, trois personnes et le pigeon, mais c'est un public !"),
  P("chiaki")("pense", "J'ai analysé notre équipe. Homer, Big Jim, Estinien, toi, moi. Nos chances de gagner sont de quatre pour cent.", {left:"chiaki:pense"}),
  M("shy", "Quatre pour cent ?! C'est tout ?!"),
  P("chiaki")("neutre", "Trois pour cent, si Homer joue après le déjeuner. Il nous faut un vrai attaquant, je pense."),
  N("Le stade municipal se résume à un terrain, deux buts et un panneau « Pelouse fraîchement tondue » qui date d'il y a six ans.", {card:"Le stade, le lendemain matin…", bg:"stade"}),
  N("Pourtant, quelqu'un est déjà là. Un garçon aux cheveux sombres frappe un ballon contre la barre transversale. Encore. Encore. Toujours au même endroit."),
  M("sweet", "Bonjour ! Euh… vous jouez vraiment bien ! Vous êtes du coin ?"),
  P("rin")("neutre", "Non. Je cherchais un terrain vide. Celui-là est vide. Même le gazon a abandonné."),
  M("idea", "Je suis Miqka, la maire de {ville}. On a un match dimanche et il nous manque un attaquant !"),
  P("rin")("neutre", "{ville}. C'est le nom d'une ville, ça ? On dirait le bruit d'un ballon qui crève."),
  M("shy", "C'est un nom PLEIN de caractère !", {effect:"shake"}),
  P("rin")("neutre", "Le caractère, ça ne marque pas de buts."),
  N("Il frappe. Le ballon touche la barre transversale, exactement au même point, et revient dans ses pieds."),
  P("rin")("neutre", "Rin Itoshi. Attaquant. Je ne joue pas pour m'amuser. Je joue pour gagner, et pour écraser ceux qui sont devant moi."),
  M("excited", "Parfait ! On veut gagner aussi ! Rejoignez l'équipe de {ville} !", {effect:"hop"}),
  P("rin")("neutre", "Montre-moi ton équipe d'abord. Si elle est nulle, je pars. Si elle est très nulle, je pars plus vite."),
  N("Une heure plus tard, toute l'équipe est alignée sur la ligne de touche. Homer mange un donut en échauffement.", {card:"L'entraînement…", bg:"stade", left:"homer:calme"}),
  HO("calme", "J'ai lu qu'il fallait s'hydrater. Alors j'ai pris un donut fourré. C'est de l'eau, en gros, avec du sucre autour."),
  P("rin")("neutre", "Toi. Défenseur. Tu ne bouges pas. Tu es grand et large. Tu es un mur. Un mur ne court pas.", {left:"rin:neutre"}),
  HO("joie", "Un poste où on ne bouge pas ?! Ce garçon est un génie !", {effect:"squish"}),
  N("Estinien atterrit au milieu du terrain, venu d'on ne sait où. La pelouse se creuse sous ses pieds.", {scr:"shake", left:"estinien:garde"}),
  ES("garde", "On m'a dit qu'il y avait un adversaire à terrasser. Où est-il ?"),
  P("rin")("neutre", "Toi, au but. Tu sautes haut. Ne saute pas trop haut. Le ballon reste sur terre.", {left:"rin:neutre"}),
  ES("garde", "Je ne promets rien.", {left:"estinien:garde"}),
  N("Premier exercice : tirs au but. Estinien bondit, dépasse la barre transversale, et revient dix secondes plus tard. Le ballon est déjà dans le filet.", {left:"rin:neutre"}),
  P("rin")("neutre", "… Bon. Changement : tu es attaquant de pointe. Tu tombes du ciel. Personne ne défend contre le ciel."),
  M("excited", "Et moi ? Je joue où, moi ?", {effect:"bounce"}),
  P("rin")("neutre", "Tire. Je veux voir."),
  N("Miqka prend son élan, ferme les yeux, et frappe de toutes ses forces. Le ballon part à l'envers, rebondit sur Big Jim, et s'arrête sagement dans les mains de Chiaki, assise sur le banc."),
  P("rin")("neutre", "… Toi, tu es pire qu'un ballon crevé."),
  M("shy", "Hé ! C'est méchant !", {effect:"shake"}),
  P("rin")("neutre", "C'est vrai. Ce qui est vrai, ce n'est pas méchant. C'est juste vrai."),
  M("pointing", "Eh bien moi, je dis que la vérité peut être dite avec des gants ! Des gants de gardien, même !"),
  P("rin")("neutre", "Les gants, c'est pour ceux qui ont peur du ballon."),
  N("Un silence s'installe. Chiaki lève la main depuis le banc.", {left:"chiaki:neutre"}),
  P("chiaki")("neutre", "Rin. Tu tires toujours au même endroit sur la barre. Pourquoi ?"),
  P("rin")("neutre", "Parce que je veux que ce soit parfait. Mon frère, lui, n'a jamais besoin de recommencer.", {left:"rin:neutre"}),
  M("idea", "Votre frère ? Il joue aussi ?"),
  P("rin")("neutre", "Ne parle pas de lui. Ce n'est pas un sujet. C'est un objectif."),
  N("Dans les vestiaires, Miqka retrouve Rin seul, les crampons à la main. L'odeur de chaussettes est presque historique.", {card:"Plus tard, au vestiaire…", bg:"vestiaire", left:"rin:neutre"}),
  M("sweet", "Je vous ai apporté une serviette. Elle est propre. Enfin, elle a été lavée par Homer, donc elle est… propre à sa façon."),
  P("rin")("neutre", "Pourquoi tu insistes ? Je t'ai dit que tu étais nulle."),
  M("shy", "Parce que je sais ce que c'est, de vouloir prouver quelque chose. J'ai fait soixante-sept ans de prison pour un Crousty. Personne ne me prenait au sérieux."),
  P("rin")("neutre", "… Soixante-sept ans. Pour un snack."),
  M("pointing", "Pour LE snack. Le meilleur. Croustillant dehors, fondant dedans."),
  P("rin")("neutre", "C'est l'histoire la plus ridicule que j'aie jamais entendue."),
  P("rin")("neutre", "Mais tu es sortie. Et tu as fondé une ville. Avec un nom de ballon crevé, mais une ville quand même."),
  M("excited", "C'était presque un compliment, ça !", {effect:"hop"}),
  P("rin")("neutre", "Non. C'était un constat. Ne t'habitue pas."),
  N("Dimanche. Les gradins sont pleins : trois habitants, le pigeon, et Big Jim qui vend des places assises sur des places debout.", {card:"Dimanche, jour de match…", bg:"stade", left:"bigjim:neutre"}),
  BJ("neutre", "Places VIP, cinq Kwak Coin. La différence avec les autres ? Je vous regarde avec respect.", {effect:"nod"}),
  HK("buste", "Billets ! Billets pour le match ! Et billets pour le même match, mais en deuxième exemplaire ! 15 Kwak Coin ^^", {left:"hancock:buste", effect:"squish"}),
  M("pointing", "Hancock ! Vous vendez chaque place deux fois ?!", {effect:"shake"}),
  HK("buste", "Une place, c'est petit. Deux personnes se serrent. C'est convivial !", {effect:"bounce"}),
  N("Coup d'envoi. Bourg-Voisin attaque. Homer, immobile, prend le ballon dans le ventre. Le ballon rebondit jusqu'au milieu du terrain.", {scr:"zoom", left:"rin:neutre"}),
  P("rin")("neutre", "Bien, le mur. Ne bouge plus jamais."),
  N("Estinien saute. Tout le monde lève la tête. Pendant que les défenseurs regardent le ciel, Rin récupère le ballon."),
  M("excited", "VAS-Y RIN ! TIRE ! TIIIIRE !", {effect:"jump", scr:"shake"}),
  N("Le tir part comme une flèche. Il touche la barre transversale, exactement au même point qu'à l'entraînement, et rentre. Le lampadaire derrière le but, lui, ne survit pas.", {scr:"flash"}),
  BJ("neutre", "Le lampadaire municipal. Ce sera une taxe. Pour le bien de la ville.", {left:"bigjim:neutre"}),
  N("Score final : {ville} 1, Bourg-Voisin 0. Les trois habitants hurlent. Le pigeon s'envole, ce qui compte comme une ola.", {left:"rin:neutre"}),
  M("excited", "On a GAGNÉ ! Quatre pour cent, Chiaki ! On a fait les quatre pour cent !", {effect:"bounce"}),
  P("chiaki")("neutre", "C'est le plus beau quatre pour cent de ma vie, je crois.", {left:"chiaki:neutre"}),
  P("rin")("neutre", "C'était un match minable. Contre une équipe minable. Avec une équipe minable.", {left:"rin:neutre"}),
  M("shy", "… Mais ?"),
  P("rin")("neutre", "Mais le mur a tenu. Le dragon a attiré tous les regards. Et ta passe ratée a lancé l'action."),
  M("idea", "Ma passe ? Quelle passe ? Ah, quand j'ai trébuché sur le ballon !"),
  P("rin")("neutre", "Ne le dis pas à voix haute. J'ai décidé que c'était une passe."),
  M("sweet", "Rin… Vous restez ? Attaquant officiel de {ville} ?"),
  P("rin")("neutre", "Je reste tant que je progresse. Le jour où cette ville m'ennuie, je pars. Préviens ton équipe."),
  M("excited", "Alors je vais faire en sorte que {ville} ne vous ennuie jamais ! Bienvenue, Rin !", {effect:"bounce"}),
  P("rin")("neutre", "Et entraîne-toi. Tous les matins. Si tu tires encore à l'envers, je te remplace par le pigeon."),
  N("Le lendemain matin, au stade, un ballon touche la barre transversale. Puis un deuxième, à l'envers, touche le panneau « Pelouse fraîchement tondue ». Rin ne dit rien. Il en pose un troisième devant Miqka."),
  {end:true}
]};

/* ---------------- TOPAZ — GESTIONNAIRE ---------------- */
ST.scenes.hire_topaz = { duo:true, chapter:"Embauche", title:"Topaz — Gestionnaire", background:"conseil", lines:[
  N("Salle du conseil de {ville}. Une lettre officielle trône sur la table. Le papier est si épais qu'il tient debout tout seul.", {right:"shy"}),
  M("shy", "« Corporation pour la Préservation Interastrale. Département des Investissements Stratégiques. Avis de visite d'audit. »"),
  M("shy", "Un audit ? On est une ville de quatre habitants, un pigeon et une salle d'arcade ! Qu'est-ce qu'ils veulent auditer ?!", {effect:"shake"}),
  BJ("neutre", "Madame la maire, en tant qu'adjoint, je vous conseille une stratégie éprouvée : on nie tout.", {left:"bigjim:neutre", effect:"nod"}),
  M("pointing", "Nier QUOI, Big Jim ?! Qu'est-ce que vous avez fait ?"),
  BJ("neutre", "Rien. Mais quand on nie tout dès le départ, on gagne du temps pour plus tard."),
  N("On frappe à la porte. Trois coups nets, parfaitement espacés.", {left:null}),
  N("Une jeune femme aux cheveux blancs entre, une tablette à la main. Derrière elle trottine un petit cochon doré qui renifle tout.", {card:"Dix heures précises…", bg:"bureau"}),
  P("topaz")("neutre", "Bonjour ! Topaz, cadre supérieure au Département des Investissements Stratégiques de la CPI. Et voici Numby. Il est là pour l'ambiance. Et pour le reste."),
  M("sweet", "B-bonjour ! Miqka, maire de {ville}. Je vous jure qu'on n'a rien fait de mal ! Enfin, pas en tant que ville !"),
  P("topaz")("neutre", "Personne n'a parlé de mal. On parle de chiffres. Les chiffres ne sont ni bons ni mauvais, ils sont justes ou faux."),
  P("topaz")("neutre", "{ville}… C'est original. Pour un nom de ville. Pour une marque de céréales, ce serait parfait."),
  M("shy", "Tout le monde me dit ça ! C'est un très beau nom !"),
  P("topaz")("neutre", "Je n'ai pas dit qu'il était laid. J'ai dit qu'il se vendrait bien. Dans ma bouche, c'est un compliment."),
  N("Numby s'arrête net. Il renifle le sol, tourne deux fois sur lui-même, puis fonce sous le bureau de Big Jim."),
  M("idea", "Il fait quoi, votre cochon ?"),
  P("topaz")("neutre", "Numby est un Trotteur des Distorsions. Il sent la valeur. Quand il s'agite comme ça, c'est qu'il y a de l'argent caché quelque part."),
  N("Numby ressort avec une enveloppe dans la gueule. Dessus, en lettres soignées : « Fonds secrets — pour le bien de la ville ».", {left:"bigjim:neutre"}),
  BJ("neutre", "Ah. Ceci est… une réserve de prévoyance. Pour les jours de pluie. Il ne pleut jamais ici, mais on ne sait jamais.", {effect:"nod"}),
  P("topaz")("neutre", "Hm hm. Je note : « réserve de prévoyance, non déclarée, conservée sous un bureau ». C'est une catégorie que je connais bien.", {left:"topaz:neutre"}),
  M("shy", "Big Jim !"),
  N("Topaz ouvre sa tablette. Des courbes s'affichent, puis des tableaux, puis un graphique en forme de donut.", {card:"Une heure d'audit plus tard…", bg:"bureau"}),
  P("topaz")("neutre", "Bon. Le bilan. Côté recettes : une salle d'arcade, un responsable des donuts, et une équipe de foot invaincue sur un match."),
  P("topaz")("neutre", "Côté dettes… Pourquoi est-ce que le même terrain a été vendu deux fois ? Et le sommet de la montagne, trois fois ?"),
  M("pointing", "HANCOCK. C'est toujours Hancock !", {effect:"shake"}),
  HK("buste", "Bonjour, bonjour ! On m'a appelé ? Je vends des audits ! Des audits favorables, garantis ! 15 Kwak Coin l'audit ^^", {left:"hancock:buste", effect:"squish"}),
  P("topaz")("neutre", "Monsieur. Vous savez ce que fait mon département ? On récupère les dettes. Même celles qui croient s'être cachées dans une autre galaxie.", {left:"topaz:neutre"}),
  HK("buste", "Ah. Alors je vous vends… mon départ. Gratuitement. Pour une fois.", {left:"hancock:buste", effect:"bounce"}),
  N("Hancock disparaît derrière la porte. Numby le poursuit trois mètres, puis revient fièrement avec une pièce dans la gueule.", {left:"topaz:neutre"}),
  P("topaz")("neutre", "Bien joué, Numby. Une pièce récupérée, c'est une pièce récupérée."),
  M("shy", "Topaz… Il y a autre chose que vous devez savoir. Sur moi. Avant que vous trouviez ça dans un tableau."),
  P("topaz")("neutre", "Je t'écoute."),
  M("shy", "J'ai fait soixante-sept ans de prison. Pour avoir volé un Crousty. Un seul."),
  P("topaz")("neutre", "Soixante-sept ans pour un snack… Quelle était la valeur marchande du Crousty, à l'époque ?"),
  M("idea", "Euh… inestimable ? Il était encore chaud."),
  P("topaz")("neutre", "Alors la peine est disproportionnée. Juridiquement, ce serait discutable. Mais je ne suis pas avocate. Je suis là pour les comptes."),
  M("sweet", "Ça ne vous dérange pas ? Une maire avec un casier ?"),
  P("topaz")("neutre", "J'ai travaillé avec des gens qui ont acheté des planètes entières avec de l'argent qu'ils n'avaient pas. Un Crousty, c'est presque reposant."),
  N("À midi, Homer entre dans la salle avec un plateau. Il a l'air très sûr de lui.", {card:"Midi…", bg:"donuts", left:"homer:joie"}),
  HO("joie", "Madame l'auditrice ! Un donut ? Totalement gratuit et sans aucune arrière-pensée !", {effect:"squish"}),
  P("topaz")("neutre", "C'est une tentative de corruption ?", {left:"topaz:neutre"}),
  HO("calme", "Non ! C'est un donut ! Bon, il est au chocolat, donc un peu une tentative de corruption.", {left:"homer:calme"}),
  P("topaz")("neutre", "… J'accepte le donut. Je refuse la corruption. Ce sont deux lignes séparées dans mon rapport.", {left:"topaz:neutre"}),
  M("excited", "Elle a pris le donut ! Elle a pris le donut, Homer !", {effect:"hop"}),
  P("topaz")("neutre", "Ne t'emballe pas. Mon rapport arrive. Et il n'est pas tendre."),
  N("Retour au conseil. Topaz pose sa tablette au centre de la table. Big Jim transpire. Chiaki dort. Rin fait des tirs contre la porte du couloir.", {card:"L'après-midi, le verdict…", bg:"conseil"}),
  P("topaz")("neutre", "Conclusion de l'audit : {ville} est désorganisée, sous-financée, et son adjoint cache de l'argent sous les meubles."),
  M("shy", "Ah. Donc… c'est la fin ? Vous allez saisir la ville ?"),
  P("topaz")("neutre", "Mais. Il y a toujours un « mais » dans un bon rapport."),
  P("topaz")("neutre", "Votre croissance est absurde. Il y a un mois, ici, c'était un terrain vague. Aujourd'hui : six employés, une équipe de foot, une marque de donuts."),
  P("topaz")("neutre", "En termes d'investissement, c'est ce qu'on appelle un actif sous-évalué. Et j'adore les actifs sous-évalués."),
  M("excited", "C'est… c'est une bonne nouvelle ?!", {effect:"bounce"}),
  P("topaz")("neutre", "C'est une proposition. Je reste en tant que gestionnaire. Je remets vos comptes en ordre, je récupère ce que Hancock a vendu deux fois, et je surveille Big Jim."),
  BJ("neutre", "Me surveiller ? Mais pourquoi ? Pour le bien de la ville ?", {left:"bigjim:neutre"}),
  P("topaz")("neutre", "Exactement. Je vois que vous connaissez la formule.", {left:"topaz:neutre"}),
  M("pointing", "Et vous, qu'est-ce que vous y gagnez ?"),
  P("topaz")("neutre", "Bonne question. Tu apprends vite. Un : Numby adore cet endroit. Deux : j'aime les villes qui ont une chance de réussir quand personne n'y croit."),
  P("topaz")("neutre", "Et trois… je veux goûter le Crousty-nut d'Homer. Il paraît qu'il a été breveté avant d'exister."),
  M("excited", "C'est tout à fait vrai ! Bienvenue à {ville}, Topaz ! Et bienvenue, Numby !", {effect:"bounce"}),
  N("Numby pousse un petit grognement satisfait et s'endort sur les pieds de Chiaki. Chiaki ne se réveille pas. Ils ont l'air de bien s'entendre."),
  P("topaz")("neutre", "Première mesure : un vrai budget. Deuxième mesure : un coffre-fort qui ne soit pas un bureau. Troisième mesure : Miqka, tu signes ici."),
  M("shy", "Qu'est-ce que je signe ?"),
  P("topaz")("neutre", "Un engagement à ne plus voler de Crousty. Pour les assurances. Rien de personnel."),
  M("shy", "… Je peux en voler un tout petit, de temps en temps ?"),
  P("topaz")("neutre", "Non."),
  N("Ce soir-là, pour la première fois, les comptes de {ville} tombent juste. Il reste même trois Kwak Coin. Numby dort dessus."),
  {end:true}
]};

/* ---------------- BAKOOL JA JA — CHEF DE TRIBU ---------------- */
ST.scenes.hire_bakool = { duo:true, chapter:"Embauche", title:"Bakool Ja Ja — Chef de tribu", background:"conseil", lines:[
  N("Grâce à Topaz, {ville} a un budget. Grâce à Big Jim, ce budget a déjà une ligne « imprévus divers ». Et grâce au budget, la ville peut organiser des élections.", {right:"idea"}),
  M("idea", "Des élections pour élire un chef de quartier ! Un vrai chef, qui représente les habitants. Ce sera très démocratique."),
  BJ("neutre", "Excellente idée, madame la maire. Je me présente. J'ai déjà imprimé les affiches. Et les bulletins. Et les résultats.", {left:"bigjim:neutre", effect:"nod"}),
  M("pointing", "Big Jim ! On n'imprime pas les résultats AVANT le vote !", {effect:"shake"}),
  BJ("neutre", "C'est une question d'efficacité. Pour le bien de la ville."),
  N("Un grondement fait trembler les vitres. Puis un deuxième, exactement en même temps. Comme si deux voix rugissaient d'un seul souffle.", {scr:"shake", left:null}),
  N("Au milieu du marché se tient une immense silhouette écailleuse, armée jusqu'aux dents. Elle a deux têtes. Les deux regardent Miqka.", {card:"Au marché…", bg:"marche"}),
  P("bakool")("neutre", "C'est ici, le concours pour devenir chef ? Bakool Ja Ja est venu. Bakool Ja Ja va gagner.", {effect:"bounce"}),
  M("shy", "B-bonjour… Je… euh… je regarde quelle tête, quand je vous parle ?"),
  P("bakool")("neutre", "Les deux. Toujours les deux. Celui qui ne regarde qu'une tête manque de respect à l'autre."),
  M("sweet", "D'accord ! Alors bonjour aux deux ! Je suis Miqka, la maire de {ville}."),
  P("bakool")("neutre", "{ville}… Hm. Dans mon pays, ce nom serait donné à un petit lézard qui fait du bruit en dormant."),
  M("shy", "C'est le nom d'une VILLE, et elle ne fait pas de bruit en dormant ! Enfin, à part Homer."),
  P("bakool")("neutre", "Chez les Mamool Ja, un enfant à deux têtes est un signe. On l'élève pour devenir fort. Pour devenir chef. Bakool Ja Ja n'a jamais cessé de s'entraîner."),
  P("bakool")("neutre", "Il prétend au trône de son pays, dans un grand rite de succession. Mais un vrai chef doit tout savoir commander. Même un petit village bruyant."),
  M("idea", "Alors vous voulez vous présenter à nos élections ? Pour vous entraîner ?"),
  P("bakool")("neutre", "Pour gagner. Bakool Ja Ja ne s'entraîne pas à perdre."),
  M("excited", "Parfait ! Il y aura trois épreuves ! Je viens de décider qu'il y aurait trois épreuves !", {effect:"hop"}),
  N("Première épreuve : la dégustation. Le stand le plus épicé du marché aligne ses brochettes. Une odeur de piment monte jusqu'au toit de la mairie.", {card:"Première épreuve : le goût", bg:"marche"}),
  M("pointing", "Le premier qui demande de l'eau a perdu ! Prêts ? Mangez !"),
  BJ("neutre", "Je proteste. Je suis un homme du Maine. Le piment le plus fort que j'aie mangé, c'est une moutarde un peu vieille.", {left:"bigjim:neutre"}),
  N("Bakool Ja Ja avale une brochette par tête. Puis deux. Puis il demande, avec un léger agacement, s'il n'y aurait pas quelque chose de plus fort.", {left:"bakool:neutre"}),
  P("bakool")("neutre", "C'est doux. C'est presque un dessert. Dans mon pays, ce piment, on le donne aux bébés pour qu'ils dorment."),
  BJ("neutre", "De… l'eau… pour le bien… de la ville…", {left:"bigjim:neutre", effect:"shake"}),
  M("excited", "Big Jim a demandé de l'eau ! Première épreuve pour Bakool Ja Ja !", {effect:"bounce"}),
  HO("joie", "Hé ! Il reste des brochettes ? Moi aussi je veux faire l'épreuve ! Je ne me présente pas, je veux juste les brochettes !", {left:"homer:joie", effect:"squish"}),
  N("Deuxième épreuve : la force. Il s'agit de porter le plus de caisses de Kwak Coin jusqu'à la mairie. Topaz a insisté pour compter chaque caisse.", {card:"Deuxième épreuve : la force", bg:"grandrue", left:"topaz:neutre"}),
  P("topaz")("neutre", "Je note tout. Une caisse qui disparaît en chemin, c'est une caisse que je vais chercher. Avec Numby."),
  N("Bakool Ja Ja soulève six caisses, une sur chaque bras, deux sur chaque épaule. Big Jim en soulève une, puis va s'asseoir pour réfléchir à sa stratégie.", {left:"bakool:neutre"}),
  M("idea", "Vous êtes vraiment très fort. Pourquoi c'est si important pour vous, de gagner ?"),
  P("bakool")("neutre", "Parce que si on ne gagne pas, on n'est rien. Un chef qui perd, personne ne le suit. Personne ne se souvient de lui."),
  M("shy", "Ce n'est pas vrai. Moi, j'ai perdu soixante-sept ans de ma vie en prison pour un Crousty. Et des gens me suivent quand même."),
  P("bakool")("neutre", "… Soixante-sept ans ? Pour une nourriture ?"),
  M("pointing", "Pour LA nourriture. Croustillante dehors, fondante dedans."),
  P("bakool")("neutre", "Hmph. Dans mon pays, aussi, on se bat pour la nourriture. Il y a des concours de cuisine plus dangereux que des batailles."),
  P("bakool")("neutre", "Mais personne ne va en prison. On va juste à l'infirmerie."),
  N("Troisième épreuve : la sagesse. Les candidats doivent emmener un groupe d'habitants en excursion dans la jungle, jusqu'aux ruines, et les ramener tous.", {card:"Troisième épreuve : la sagesse", bg:"jungle"}),
  N("Le groupe : Chiaki, endormie sur un brancard. Rin, qui refuse de marcher derrière quelqu'un. Homer, qui veut s'arrêter tous les dix mètres.", {left:"bakool:neutre"}),
  P("bakool")("neutre", "En avant ! Bakool Ja Ja marche devant ! Suivez la plus forte force !", {effect:"bounce"}),
  P("rin")("neutre", "Je ne suis personne. Je marche où je veux.", {left:"rin:neutre"}),
  HO("calme", "Je peux marcher n'importe où, du moment que c'est en descente et qu'il y a un snack au bout.", {left:"homer:calme"}),
  N("Une heure plus tard, le groupe est éparpillé dans la jungle. Bakool Ja Ja arrive seul aux ruines.", {bg:"ruines", left:"bakool:neutre"}),
  P("bakool")("neutre", "… Il n'y a personne derrière Bakool Ja Ja."),
  M("sweet", "Si. Il y a moi. Je vous ai suivi. Mais les autres se sont perdus."),
  P("bakool")("neutre", "Pourquoi ils ne suivent pas ? Bakool Ja Ja est le plus fort."),
  M("idea", "Parce que vous marchez trop vite. Un chef, ce n'est pas celui qui arrive le premier. C'est celui qui fait arriver tout le monde."),
  P("bakool")("neutre", "… Ça, c'est une phrase de sage. Où est-ce que tu as appris ça ?"),
  M("shy", "En prison. Pendant la promenade. Les gardiens attendaient toujours les plus lents."),
  N("Bakool Ja Ja reste silencieux un long moment. Puis ses deux têtes poussent un soupir en même temps.", {left:"bakool:neutre"}),
  P("bakool")("neutre", "Bon. On retourne les chercher. Tous. Même celui qui mange tout le temps."),
  N("Il retrouve Chiaki endormie sous une fougère, Rin qui tirait dans des noix de coco, et Homer coincé dans une racine, en train de manger une banane.", {card:"Au coucher du soleil…", bg:"ruines"}),
  HO("joie", "Il est revenu me chercher ! Personne ne revient jamais me chercher ! Sauf Marge. Et la police.", {left:"homer:joie", effect:"squish"}),
  P("chiaki")("neutre", "Tu as ralenti pour nous. C'est un bon réglage, je trouve.", {left:"chiaki:neutre"}),
  P("rin")("neutre", "Tu marches encore trop lentement. Mais tu es revenu. C'est noté.", {left:"rin:neutre"}),
  N("Retour à {ville}, à la nuit tombée. Un stand improvisé attend les candidats devant la mairie.", {bg:"grandrue", left:"hancock:buste"}),
  HK("buste", "Bonsoir ! Je vends des voix ! Des voix pour l'élection ! Chaque voix vendue deux fois, pour plus de démocratie ! 15 Kwak Coin ^^", {effect:"squish"}),
  M("pointing", "HANCOCK ! On ne vend PAS les voix ! Et encore moins deux fois !", {effect:"shake"}),
  P("bakool")("neutre", "Toi. Le marchand. Tu as vendu une voix à Bakool Ja Ja ce matin. Et la même voix à l'homme chauve.", {left:"bakool:neutre"}),
  HK("buste", "C'était… un forfait famille ? Bonne soirée !", {left:"hancock:buste", effect:"bounce"}),
  N("Hancock prend la fuite. Big Jim range discrètement un reçu dans sa poche.", {left:"bigjim:neutre"}),
  N("Le dépouillement a lieu sous la lune. Topaz compte. Numby renifle chaque bulletin. Le résultat est sans appel.", {card:"Le dépouillement…", bg:"conseil", left:"topaz:neutre"}),
  P("topaz")("neutre", "Résultats : Bakool Ja Ja, quatre voix. Big Jim, une voix. Et un bulletin au nom de « Crousty », écriture de la maire."),
  M("shy", "Ce n'est pas moi. C'est quelqu'un qui a la même écriture que moi."),
  BJ("neutre", "Je reconnais ma défaite. Pour le bien de la ville. Mais je demande un recompte. Pour le bien de moi.", {left:"bigjim:neutre"}),
  P("bakool")("neutre", "Bakool Ja Ja a gagné. Mais pas tout seul. Bakool Ja Ja a gagné parce qu'il est revenu chercher les autres.", {left:"bakool:neutre"}),
  M("excited", "Alors c'est officiel ! Bakool Ja Ja, chef de tribu de {ville} !", {effect:"bounce"}),
  P("bakool")("neutre", "Chef de tribu. Mais un jour, Bakool Ja Ja repartira dans son pays, pour le grand rite. Il faudra le laisser partir."),
  M("sweet", "Promis. Et quand vous partirez, on marchera tous derrière vous. Lentement."),
  P("bakool")("neutre", "Hmph. Petite maire. Tu n'es pas forte. Mais tu es… têtue. Les deux têtes de Bakool Ja Ja respectent ça."),
  N("Cette nuit-là, le nouveau chef de tribu fait le tour de la ville pour vérifier que tout le monde est bien rentré. Il trouve Homer endormi sur un banc, et le porte jusque chez lui sans rien dire."),
  {end:true}
]};

/* ---------------- ZENOS — CHAMPION D'ARÈNE ---------------- */
ST.scenes.hire_zenos = { duo:true, chapter:"Embauche", title:"Zenos — Champion d'arène", background:"grandrue", lines:[
  N("{ville} a désormais un chef de tribu. Bakool Ja Ja a rendu le marché très ordonné. Trop ordonné. Il s'ennuie.", {right:"shy", left:"bakool:neutre"}),
  P("bakool")("neutre", "Personne ne veut se battre contre Bakool Ja Ja. Un chef sans rival, c'est un chef qui rouille."),
  M("idea", "Et si on construisait une arène ? Pour des tournois ! Avec des règles, des arbitres, et un stand de Crousty à l'entrée."),
  P("bakool")("neutre", "Le stand de Crousty, c'est pour toi. Mais l'arène, Bakool Ja Ja approuve."),
  N("Trois semaines plus tard, les vieilles pierres d'une arène sortent de terre. Big Jim a payé. Personne ne sait avec quel argent. Topaz le sait, et elle a pris des notes.", {card:"Trois semaines plus tard…", bg:"arene", left:"topaz:neutre"}),
  P("topaz")("neutre", "Ligne budgétaire : « arène, colonnes, lions décoratifs ». Big Jim, les lions décoratifs, ils ne sont pas décoratifs. Ils bougent."),
  BJ("neutre", "Ce sont des lions d'occasion. Un très bon prix.", {left:"bigjim:neutre"}),
  N("Le jour de l'inauguration, le premier tournoi commence. Rin marque un but dans l'arène, ce qui n'est pas le sport prévu. Bakool Ja Ja gagne tous ses combats.", {bg:"arene", left:"bakool:neutre"}),
  N("Puis le silence tombe. Un homme entre dans l'arène sans y avoir été invité. De longs cheveux blonds. Un regard qui s'ennuie de tout.", {scr:"flash", left:"zenos:neutre"}),
  P("zenos")("neutre", "Alors c'est ici que l'on se bat. J'ai entendu les cris depuis la montagne. J'espérais quelque chose de… plus amusant.", {effect:"lean"}),
  M("shy", "Bonjour ! Bienvenue à l'arène de {ville} ! Vous… vous êtes inscrit ? Il faut remplir le formulaire B-12."),
  P("zenos")("neutre", "Je ne remplis pas de formulaires. Je chasse. Et pour l'instant, rien ici ne mérite d'être chassé."),
  P("bakool")("neutre", "Bakool Ja Ja mérite. Viens te battre, l'homme qui s'ennuie !", {left:"bakool:neutre", effect:"bounce"}),
  N("Le combat dure quatorze secondes. Bakool Ja Ja se retrouve assis dans le sable, ses deux têtes un peu étonnées.", {scr:"shake", left:"zenos:neutre"}),
  P("zenos")("neutre", "Pas mal. Deux têtes, et pourtant une seule idée à la fois. Tu as de la force, mais tu n'as pas encore faim."),
  P("bakool")("neutre", "… Bakool Ja Ja a faim. Tout le temps. Bakool Ja Ja reviendra.", {left:"bakool:neutre"}),
  P("zenos")("neutre", "Bien. Reviens. C'est la seule chose qui compte.", {left:"zenos:neutre"}),
  M("pointing", "Hé ! On ne vient pas dans MON arène pour battre MON chef de tribu sans formulaire !", {effect:"shake"}),
  P("zenos")("neutre", "Et toi, petite chose ? Tu veux te battre ?"),
  M("shy", "Non. Moi, je veux qu'on remplisse le formulaire. Et qu'on dise bonjour."),
  P("zenos")("neutre", "… Personne ne m'a jamais demandé de dire bonjour."),
  M("sweet", "Eh bien, il y a un début à tout. Bonjour. Je suis Miqka. La maire."),
  P("zenos")("neutre", "Zenos. Je suis prince d'un empire. Mais les palais m'ennuient. Les conseils m'ennuient. Les gens m'ennuient."),
  M("idea", "Et qu'est-ce qui ne vous ennuie pas ?"),
  P("zenos")("neutre", "La chasse. Un adversaire qui me regarde dans les yeux sans trembler. Le moment où le combat devient vraiment intéressant."),
  M("shy", "Ah. Moi, ce qui ne m'ennuie pas, c'est les Crousty. On n'a pas les mêmes loisirs."),
  N("Le soir, Zenos s'est installé sur le grand fauteuil de la salle d'honneur de l'arène. Personne ne lui a dit qu'il pouvait. Personne n'ose lui dire de partir.", {card:"Le soir, dans la salle d'honneur…", bg:"trone", left:"zenos:neutre"}),
  BJ("neutre", "Madame la maire. Ce monsieur s'est assis sur MON fauteuil. Je l'ai acheté pour moi. Pour le bien de la ville.", {left:"bigjim:neutre"}),
  P("zenos")("neutre", "Il est confortable. Je le garde.", {left:"zenos:neutre"}),
  BJ("neutre", "… Je vais commander un autre fauteuil. Un plus grand.", {left:"bigjim:neutre"}),
  N("Big Jim repart, digne, en serrant son carnet de formulaires contre lui."),
  M("sweet", "Vous savez, si vous voulez rester, il faut un travail. Ici, tout le monde travaille. Même Homer. Enfin… surtout Homer, il fait des siestes de travail."),
  P("zenos")("neutre", "Un travail. Pour moi. Et lequel, madame la maire ?", {left:"zenos:neutre"}),
  M("excited", "Champion de l'arène ! Vous défendez le titre ! Tout le monde peut venir vous défier, et vous gagnez, et ça fait venir des visiteurs !", {effect:"hop"}),
  P("zenos")("neutre", "Et si personne n'est à ma hauteur ?"),
  M("pointing", "Alors on entraînera des gens jusqu'à ce qu'ils le soient ! C'est ça, une ville. Ça grandit."),
  P("zenos")("neutre", "… Intéressant. Tu cultives des adversaires. Comme un jardinier qui ferait pousser des loups."),
  M("shy", "Je n'ai pas dit des loups ! J'ai dit des gens !"),
  N("Une ombre se pose sur le rebord de la fenêtre. Une silhouette en armure, une lance sur l'épaule, et un sandwich à moitié mangé.", {left:"estinien:garde"}),
  ES("garde", "Miqka. J'ai entendu dire qu'un prince venait de faire tomber Bakool. Je voulais voir ça de plus près."),
  P("zenos")("neutre", "Un chevalier dragon. Enfin, quelqu'un qui tient debout sans trembler. Tu veux danser, lancier ?", {left:"zenos:neutre"}),
  ES("garde", "Pas ce soir. Ce soir, je mange. Demain, à l'aube, au sommet de la montagne. Si tu tiens à te faire mal.", {left:"estinien:garde"}),
  P("zenos")("neutre", "Ah… Enfin. Un rendez-vous qui vaut la peine.", {left:"zenos:neutre", effect:"nod"}),
  M("shy", "Attendez ! Personne ne se bat au sommet de la montagne ! Il y a un formulaire pour ça aussi !"),
  N("À l'aube, au sommet. Le vent hurle. Estinien et Zenos se font face. Miqka est là, en pyjama, avec un sifflet et un thermos de cacao.", {card:"À l'aube, au sommet de la montagne…", bg:"montagne", left:"zenos:neutre"}),
  M("pointing", "Règles officielles ! Pas de coups dans le dos ! Pas de chute dans le vide ! Et le perdant offre le petit-déjeuner !", {effect:"bounce"}),
  ES("garde", "Je n'ai jamais perdu un petit-déjeuner.", {left:"estinien:garde"}),
  P("zenos")("neutre", "Et moi, je n'ai jamais payé un petit-déjeuner.", {left:"zenos:neutre"}),
  N("Le combat est terrible. Estinien bondit si haut qu'il disparaît dans les nuages. Zenos l'attend en souriant. Le sol tremble. Des pierres roulent. Le pigeon de la mairie s'envole, scandalisé.", {scr:"shake", left:"estinien:garde"}),
  N("Au bout d'une heure, ils s'arrêtent en même temps. Ni l'un ni l'autre ne tombe. Ils respirent fort. Ils se regardent.", {left:"zenos:neutre"}),
  P("zenos")("neutre", "Match nul. C'est… nouveau. C'est la première fois que je m'amuse depuis très longtemps."),
  ES("garde", "Je reviendrai. Et la prochaine fois, je ne serai pas fatigué par six sandwichs.", {left:"estinien:garde"}),
  M("excited", "Match nul ! Ça veut dire que vous offrez tous les deux le petit-déjeuner ! À moi !", {effect:"hop"}),
  N("Au retour, la boutique de donuts ouvre à peine. Homer sert les deux guerriers sans poser de questions, et prend un donut pour chaque coup échangé.", {card:"Plus tard, à la boutique de donuts…", bg:"donuts", left:"homer:joie"}),
  HO("joie", "Vous vous êtes battus toute la nuit ? Moi aussi ! Contre un frigo. J'ai gagné. Le frigo est vide.", {effect:"squish"}),
  P("zenos")("neutre", "Toi… tu as l'air de ne jamais t'ennuyer. Quel est ton secret ?", {left:"zenos:neutre"}),
  HO("calme", "Je ne pense à rien. Jamais. C'est très reposant.", {left:"homer:calme"}),
  P("zenos")("neutre", "… Je ne pourrais jamais. Mais je respecte la constance.", {left:"zenos:neutre"}),
  N("De retour à l'arène, un panneau neuf a été installé à l'entrée : « Champion en titre : Zenos. Défis le mardi. Formulaire obligatoire. »", {bg:"arene"}),
  P("zenos")("neutre", "Un formulaire. Pour me défier. Tu es une étrange petite maire.", {left:"zenos:neutre"}),
  M("sweet", "Et vous êtes un étrange grand prince. On va bien s'entendre."),
  P("zenos")("neutre", "Ne te méprends pas. Je reste parce que cette ville fait pousser des adversaires. Pas parce que tu m'as dit bonjour."),
  M("idea", "Bien sûr. Mais vous m'avez répondu bonjour ce matin. Je l'ai noté."),
  P("zenos")("neutre", "… Hm. Bonjour, mon amie. Va chercher tes Crousty. J'ai des gens à entraîner."),
  N("Ce soir-là, Bakool Ja Ja est revenu défier le champion. Il a perdu en vingt-six secondes. C'est déjà presque deux fois mieux. Zenos a hoché la tête, et c'est tout ce qu'il fallait.", {left:"bakool:neutre"}),
  {end:true}
]};

/* ---------------- AVENTURINE — DIRECTEUR DU CASINO ---------------- */
ST.scenes.hire_aventurine = { duo:true, chapter:"Embauche", title:"Aventurine — Directeur du casino", background:"bureau", lines:[
  N("Bureau de la gestionnaire. Topaz regarde les comptes de {ville}. Numby regarde Topaz. Miqka regarde le plafond.", {right:"shy", left:"topaz:neutre"}),
  P("topaz")("neutre", "Les recettes de l'arène sont bonnes. Mais il faut diversifier. Une ville qui ne vit que d'un champion, c'est un risque."),
  M("idea", "On pourrait ouvrir un casino ! Avec des lumières, de la musique, et des jetons en forme de Crousty !"),
  P("topaz")("neutre", "Un casino… Il faudrait quelqu'un qui sait gérer le risque. Et je ne connais qu'une personne qui aime autant le risque."),
  P("topaz")("neutre", "Malheureusement, c'est un collègue. Il va venir. Je le sens. Il vient toujours quand on parle de lui."),
  N("Un claquement de dés. La porte s'ouvre. Un homme élégant entre, deux dés dans la main, un sourire qui semble avoir déjà gagné.", {scr:"flash", left:"aventurine:neutre"}),
  P("aventurine")("neutre", "Topaz ! Quelle chance ! J'étais justement en train de parier que tu parlerais de moi aujourd'hui. Gagné.", {effect:"lean"}),
  P("topaz")("neutre", "Aventurine. Tu as parié contre qui ?", {left:"topaz:neutre"}),
  P("aventurine")("neutre", "Contre moi-même. C'est le seul adversaire qui accepte toujours mes conditions.", {left:"aventurine:neutre"}),
  M("sweet", "Bonjour ! Je suis Miqka, la maire de {ville}. Vous êtes un collègue de Topaz ?"),
  P("aventurine")("neutre", "Collègue, rival, complice selon les jours. Nous travaillons tous les deux pour une très grande compagnie, qui aime beaucoup les chiffres."),
  P("aventurine")("neutre", "Elle, elle compte. Moi, je joue. Et en fin d'année, on additionne."),
  M("excited", "Vous voulez diriger notre casino ?! On n'a pas encore de casino, mais on a l'idée !", {effect:"hop"}),
  P("aventurine")("neutre", "Une ville qui me propose un casino qui n'existe pas encore. C'est mon genre de pari. Mais d'abord… je dois savoir si sa maire sait jouer."),
  M("shy", "Je sais jouer aux dés. Un peu. En prison, on jouait avec des boulettes de pain. Mais on mangeait souvent les dés."),
  P("aventurine")("neutre", "La prison ? Ah, je vois. Un passé intéressant. Je ne pose pas de questions. Je ne parle pas du mien non plus. Ça nous fera un point commun."),
  N("Le soir même, Aventurine emmène Miqka sur la grande avenue des lumières, voir à quoi ressemble un vrai casino.", {card:"Le soir, sur l'avenue des lumières…", bg:"strip"}),
  M("excited", "C'est magnifique ! Tout brille ! On dirait un Crousty géant fait de néons !", {effect:"bounce"}),
  P("aventurine")("neutre", "Tout ce qui brille ici est construit sur une seule idée : la maison gagne toujours. Sauf quand c'est moi qui joue.", {left:"aventurine:neutre"}),
  M("idea", "Et pourquoi vous gagnez toujours ?"),
  P("aventurine")("neutre", "Parce que je mise tout. Quand on n'a pas peur de perdre, la chance finit par avoir peur de vous."),
  M("shy", "Moi, j'ai peur de tout perdre. J'ai déjà perdu soixante-sept ans. Je n'ai plus beaucoup de jetons."),
  P("aventurine")("neutre", "Alors tu es plus riche que tu ne le crois. Tu as encore des choses à perdre. Ça veut dire que tu tiens à quelque chose."),
  N("Au casino, Aventurine propose un marché. Un seul pari. S'il gagne, il dirige le casino de {ville} comme il l'entend. Si Miqka gagne, il le dirige quand même, mais avec ses règles à elle.", {card:"Au casino…", bg:"casino", left:"aventurine:neutre"}),
  M("pointing", "Attendez… Dans les deux cas, vous dirigez le casino !"),
  P("aventurine")("neutre", "Exactement. La vraie question, c'est : avec quelles règles ? C'est toujours ça, l'enjeu."),
  N("Toute la ville est venue regarder. Big Jim a acheté un costume. Hancock vend du popcorn. Rin refuse de s'asseoir derrière quelqu'un.", {left:"bigjim:neutre"}),
  BJ("neutre", "Je mise cent Kwak Coin sur monsieur Aventurine. Pour le bien de la ville. Et de mon portefeuille.", {effect:"nod"}),
  HK("buste", "Popcorn ! Popcorn ! Chaque sachet vendu deux fois ! Le deuxième est vide mais il est moins cher ! ^^", {left:"hancock:buste", effect:"squish"}),
  P("chiaki")("neutre", "Je peux calculer les probabilités, si tu veux. Mais ça gâcherait le suspense, je pense.", {left:"chiaki:neutre"}),
  P("aventurine")("neutre", "Le jeu est simple. Trois dés. Le plus grand total gagne. Les dames d'abord.", {left:"aventurine:neutre"}),
  N("Miqka souffle sur les dés, les serre très fort, puis les lance. Un deux, un un, et un trois. Total : six. Le public soupire.", {scr:"zoom"}),
  M("shy", "Six… C'est nul, six. Même Homer ferait mieux en dormant."),
  HO("calme", "Merci, Miqka. J'ai fait onze, ce matin. En dormant, c'est vrai.", {left:"homer:calme"}),
  P("aventurine")("neutre", "À moi. Tout ou rien.", {left:"aventurine:neutre"}),
  N("Les dés roulent longtemps. Très longtemps. L'un d'eux tourne sur la tranche, puis s'arrête. Un, un, et… trois. Six. Égalité.", {scr:"shake"}),
  P("aventurine")("neutre", "… Égalité. Intéressant. Je ne fais jamais égalité. Jamais."),
  P("topaz")("neutre", "Je l'ai noté. Pour la première fois, la chance d'Aventurine a hésité. Numby, c'est historique.", {left:"topaz:neutre"}),
  M("idea", "Égalité, ça veut dire qu'on fait les règles ensemble !"),
  P("aventurine")("neutre", "Ensemble ? Je ne fais rien ensemble. Je mise seul, je gagne seul.", {left:"aventurine:neutre"}),
  M("sweet", "Ici, personne ne gagne seul. Bakool l'a appris dans la jungle. Zenos l'a appris sur la montagne. Vous l'apprendrez au casino."),
  N("Le lendemain matin, dans le bureau de Topaz, ils rédigent les règles du casino. Miqka a apporté des Crousty. Aventurine a apporté des dés. Topaz a apporté un calculateur.", {card:"Le lendemain matin, au bureau…", bg:"bureau", left:"aventurine:neutre"}),
  M("pointing", "Règle numéro un : on ne mise jamais plus que ce qu'on peut perdre !"),
  P("aventurine")("neutre", "Ça, c'est une règle pour les autres. Pas pour moi. Mais d'accord, pour les clients."),
  M("pointing", "Règle numéro deux : Hancock n'a pas le droit de revendre les jetons."),
  P("topaz")("neutre", "Elle les a déjà revendus. Deux fois. Numby a retrouvé l'argent sous le stand de popcorn.", {left:"topaz:neutre"}),
  M("pointing", "Règle numéro trois : chaque soir, une partie de la recette sert à construire quelque chose pour la ville."),
  P("aventurine")("neutre", "Un casino qui rend de l'argent à la ville. C'est le pari le plus absurde que j'aie jamais vu.", {left:"aventurine:neutre"}),
  P("aventurine")("neutre", "… J'aime bien."),
  BJ("neutre", "Je propose une règle numéro quatre. L'adjoint au maire a droit à une table réservée. Pour le bien de la ville.", {left:"bigjim:neutre"}),
  M("shy", "Refusé. Mais tu as droit à une chaise."),
  BJ("neutre", "J'accepte la chaise. Je la ferai agrandir."),
  N("Le soir de l'ouverture, le casino de {ville} brille de mille feux. Zenos défie les clients aux dés, et perd souvent, ce qui le fascine.", {card:"Le soir de l'ouverture…", bg:"casino", left:"zenos:neutre"}),
  P("zenos")("neutre", "Encore. Je ne comprends pas cet adversaire. Il ne me regarde pas. Il roule. C'est admirable."),
  P("bakool")("neutre", "Bakool Ja Ja a gagné trois fois. Les deux têtes ont triché. Une regardait les dés de l'autre côté.", {left:"bakool:neutre"}),
  P("aventurine")("neutre", "Interdit de regarder avec deux têtes à la fois. Je l'ajoute aux règles. Règle numéro cinq.", {left:"aventurine:neutre"}),
  N("Tard dans la nuit, quand tout le monde est parti, Aventurine reste seul à une table, à lancer ses dés pour lui-même.", {trans:"black", left:"aventurine:neutre"}),
  M("sweet", "Vous ne rentrez pas ?"),
  P("aventurine")("neutre", "Je regarde. Six. Encore six. Depuis l'égalité, les dés font souvent six. Comme s'ils voulaient me rappeler quelque chose."),
  M("idea", "Peut-être qu'ils veulent dire que vous avez trouvé une table où vous n'êtes pas seul."),
  P("aventurine")("neutre", "Hm. Ou peut-être qu'ils sont pipés. Les deux options sont intéressantes. Bonne nuit, madame la maire."),
  M("excited", "Bonne nuit, monsieur le directeur du casino !", {effect:"hop"}),
  N("Sur le registre du casino, une ligne a été ajoutée à la main : « Dette de la maison envers Miqka : une égalité. » Personne ne sait vraiment ce que ça vaut. Aventurine dit que ça vaut tout."),
  {end:true}
]};

/* ---------------- FANDANIEL — MAÎTRE DES FESTIVITÉS ---------------- */
ST.scenes.hire_fandaniel = { duo:true, chapter:"Embauche", title:"Fandaniel — Maître des festivités", background:"grandrue", lines:[
  N("{ville} a un casino, une arène, un chef de tribu et un budget surveillé par un petit chien. Il ne manque plus qu'une chose : une grande fête.", {right:"excited"}),
  M("excited", "Une fête pour l'anniversaire de {ville} ! Avec des feux d'artifice, du théâtre, et un Crousty géant au milieu !", {effect:"hop"}),
  P("topaz")("neutre", "Budget des feux d'artifice : modéré. Très modéré. Numby a peur du bruit.", {left:"topaz:neutre"}),
  M("idea", "Il nous faut un spécialiste. Quelqu'un qui adore le spectacle. Quelqu'un qui n'a peur de rien."),
  N("BOUM. Une gerbe d'étincelles violettes explose au-dessus de la mairie. Une silhouette masquée apparaît dans la fumée, les bras grands ouverts.", {scr:"flash", left:"fandaniel:neutre"}),
  P("fandaniel")("neutre", "Quelqu'un a parlé de SPECTACLE ? Ah, enfin ! Une ville qui a du goût ! Applaudissez, applaudissez, je vous en prie !", {effect:"jump"}),
  M("shy", "… Euh. Clap. Clap. Bonjour ? Vous venez d'où ? Vous avez traversé le toit ?"),
  P("fandaniel")("neutre", "D'où je viens ? D'un très vieux mot, d'une très vieille histoire, et d'une très, très mauvaise humeur. Mais aujourd'hui, je suis d'humeur festive !"),
  P("fandaniel")("neutre", "Appelez-moi Fandaniel. Metteur en scène. Artificier. Amateur de grandes fins, de préférence spectaculaires."),
  M("sweet", "Je suis Miqka, la maire de {ville}. On organise une fête ! Vous voulez nous aider ?"),
  P("fandaniel")("neutre", "{ville}… Oh non. Non, non, non. Ce nom n'a aucun panache. Il faut le changer. Pour la fête, on l'appellera « Fandanielopolis » !"),
  M("pointing", "NON ! On ne change pas le nom de la ville ! Il a été choisi avec amour !", {effect:"shake"}),
  P("fandaniel")("neutre", "« Fandanielburg » ? « La Cité du Grand Final » ? « Pandémonium-sur-Mer » ?"),
  M("pointing", "Non, non, et on n'a même pas de mer !"),
  P("fandaniel")("neutre", "Quelle tristesse ! Quelle tragédie ! J'adore les tragédies. Bon. Je ferai la fête quand même. Mais sous protestation !"),
  N("Le lendemain, Fandaniel prend possession du vieux théâtre. Il a déjà repeint les rideaux, et tout le monde a un rôle, qu'il le veuille ou non.", {card:"Le lendemain, au théâtre…", bg:"theatre", left:"fandaniel:neutre"}),
  P("fandaniel")("neutre", "Distribution ! Big Jim, tu joueras le tyran. Non, ne dis rien, tu es parfait.", {effect:"bounce"}),
  BJ("neutre", "Je ne suis pas un tyran. Je suis un adjoint. C'est très différent. Pour le bien de la ville.", {left:"bigjim:neutre"}),
  P("fandaniel")("neutre", "Exactement ce qu'aurait dit un tyran ! Bravo ! Homer, tu joueras… le public. Tu dois juste manger et rire.", {left:"fandaniel:neutre"}),
  HO("joie", "C'est le meilleur rôle que j'aie jamais eu ! Je peux répéter tout de suite ?", {left:"homer:joie", effect:"squish"}),
  P("fandaniel")("neutre", "Hancock ! Tu joueras la marchande qui vend le même trésor deux fois.", {left:"fandaniel:neutre"}),
  HK("buste", "Ce n'est pas un rôle, ça. C'est mon métier ! Mais j'accepte. 15 Kwak Coin le billet ^^", {left:"hancock:buste"}),
  P("fandaniel")("neutre", "Et le rôle principal… celui qui finit dans les flammes, dans un grand éclat de rire tragique… sera tenu par…", {left:"fandaniel:neutre"}),
  N("Une ombre se lève au fond de la salle. De longs cheveux blonds. Un regard qui s'ennuie déjà.", {left:"zenos:neutre"}),
  P("zenos")("neutre", "Toi. Je te connais. Tu fais toujours trop de bruit pour pas grand-chose."),
  P("fandaniel")("neutre", "Ah, Zenos ! Mon partenaire préféré de catastrophes ! Tu veux le premier rôle ? Tu meurs à la fin, c'est très beau.", {left:"fandaniel:neutre"}),
  P("zenos")("neutre", "Je ne joue pas. Je me bats. Si ton spectacle contient un vrai combat, je viendrai. Sinon, je dors.", {left:"zenos:neutre"}),
  P("fandaniel")("neutre", "Il y aura un dragon ! En carton ! Mais un très gros carton !", {left:"fandaniel:neutre"}),
  P("zenos")("neutre", "… Je dors.", {left:"zenos:neutre"}),
  M("idea", "Vous vous connaissez ? Vous êtes amis ?"),
  P("fandaniel")("neutre", "Amis ? Non ! Nous avons… travaillé ensemble. Sur des projets ambitieux. Qui ont tous très mal fini. C'était merveilleux.", {left:"fandaniel:neutre"}),
  M("shy", "… Je préfère ne pas savoir. Je n'ai pas besoin de soixante-sept ans de prison en plus."),
  N("Une semaine de répétitions plus tard, la veille de la fête. Fandaniel a installé ses feux d'artifice sur le toit de la mairie. Beaucoup de feux d'artifice. Beaucoup trop.", {card:"La veille de la fête, sur le toit…", bg:"toit", left:"fandaniel:neutre"}),
  M("pointing", "Fandaniel ! C'est quoi ce gros rouleau marqué « FIN DU MONDE » ?!", {effect:"shake"}),
  P("fandaniel")("neutre", "Le bouquet final, voyons ! Une petite fin du monde, juste pour rire. Personne ne sera blessé. Probablement. Très probablement."),
  ES("garde", "Je surveille ce toit. Si une seule fusée part dans la mauvaise direction, je la rattrape. Et je te la rends.", {left:"estinien:garde"}),
  P("fandaniel")("neutre", "Un chevalier dragon pour garder mes feux ! Quel luxe ! Cette ville est un théâtre parfait !", {left:"fandaniel:neutre"}),
  M("sweet", "Pourquoi vous aimez autant que tout explose ?"),
  P("fandaniel")("neutre", "Parce que quand tout explose, plus rien n'est ennuyeux. Plus de règles, plus de formulaires, plus de lendemains. Juste… le bouquet final."),
  M("idea", "Mais si tout explose, il n'y a plus de spectateurs pour applaudir."),
  P("fandaniel")("neutre", "… Ah."),
  P("fandaniel")("neutre", "C'est une objection technique très pertinente. Je n'y avais jamais pensé sous cet angle."),
  M("excited", "Alors on fait un bouquet final où tout le monde reste pour applaudir ! C'est beaucoup plus difficile ! Un vrai défi d'artiste !", {effect:"hop"}),
  P("fandaniel")("neutre", "Un spectacle où rien n'est détruit… Quelle idée scandaleuse. Quelle idée… délicieuse. J'accepte le défi !"),
  N("Le soir de la fête, toute la ville est réunie sur la place. Le théâtre a joué à guichets fermés, deux fois par billet. La nuit tombe. Les feux s'allument.", {card:"Le soir de la fête…", bg:"feux", left:"fandaniel:neutre"}),
  P("fandaniel")("neutre", "Mesdames, messieurs, têtes uniques et têtes doubles ! Voici le GRAND FINAL de {ville} !", {effect:"jump"}),
  N("Des gerbes d'or et de violet montent dans le ciel. Elles dessinent un Crousty. Puis une pièce de Kwak Coin. Puis un grand cœur, et dedans, le nom de la ville.", {scr:"flash"}),
  M("excited", "Il a écrit le nom de la ville ! Le vrai nom ! Pas Fandanielopolis !", {effect:"bounce"}),
  P("fandaniel")("neutre", "Ne te réjouis pas trop vite, petite maire. Regarde la dernière fusée."),
  N("La dernière fusée explose en petites lettres violettes : « … et un jour, Fandanielopolis ! » Le public éclate de rire.", {scr:"zoom"}),
  HO("joie", "C'est le meilleur spectacle de ma vie ! Et j'avais le meilleur rôle : le public !", {left:"homer:joie", effect:"squish"}),
  P("bakool")("neutre", "Bakool Ja Ja a eu peur. Une tête seulement. L'autre a applaudi.", {left:"bakool:neutre"}),
  P("zenos")("neutre", "… Pas mal. J'ai presque eu envie de me réveiller.", {left:"zenos:neutre"}),
  P("aventurine")("neutre", "J'avais parié que rien n'exploserait de travers. Gagné. Topaz, tu me dois un café.", {left:"aventurine:neutre"}),
  P("topaz")("neutre", "Budget des feux : dépassé de quatre cents pour cent. Mais la recette du théâtre compense. De justesse.", {left:"topaz:neutre"}),
  N("Une fusée égarée file vers le bar. Estinien saute, l'attrape au vol, et la renvoie dans le ciel où elle éclate en forme de dragon.", {left:"estinien:garde"}),
  P("fandaniel")("neutre", "Bravo, le lancier ! Je t'engage ! Non, attends, c'est la maire qui engage. Madame la maire, engagez-le une deuxième fois !", {left:"fandaniel:neutre"}),
  M("sweet", "Et vous, Fandaniel ? Vous restez ? Maître des festivités de {ville} ?"),
  P("fandaniel")("neutre", "Maître des festivités… Moi qui voulais la fin de tout, me voilà chargé des débuts de fête. Le destin a un sens de l'humour atroce."),
  P("fandaniel")("neutre", "J'accepte. Mais je garde le rouleau « FIN DU MONDE » dans un placard. Pour une occasion vraiment spéciale."),
  M("pointing", "Le placard sera fermé à clé. Et la clé, c'est Topaz qui la garde."),
  N("Le lendemain, une affiche a été collée sur la porte de la mairie : « Prochain spectacle : bientôt. Ville rebaptisée : pas encore. » Miqka l'a laissée. Elle trouvait ça plutôt drôle."),
  {end:true}
]};

/* ---------------- SINBAD — ROI ALLIÉ ---------------- */
ST.scenes.hire_sinbad = { duo:true, chapter:"Embauche", title:"Sinbad — Roi allié", background:"grandrue", lines:[
  N("Depuis la fête, on parle de {ville} jusque de l'autre côté de l'océan. Un matin, une lettre arrive, scellée d'un sceau royal.", {right:"idea"}),
  M("idea", "« Le roi de Sindria souhaite rencontrer la maire de {ville} au port, pour discuter d'une alliance. » Une alliance ! Avec un roi !"),
  BJ("neutre", "Un roi. Je vais préparer un discours. Et un formulaire d'alliance. Et une petite commission, pour le bien de la ville.", {left:"bigjim:neutre"}),
  M("pointing", "Pas de commission, Big Jim ! On reçoit un roi, on reste digne !"),
  N("Au port, un navire immense jette l'ancre. Sur le pont, un homme aux longs cheveux violets salue la foule comme s'il la connaissait depuis toujours.", {card:"Au port…", bg:"port", left:"sinbad:neutre"}),
  P("sinbad")("neutre", "Bonjour, {ville} ! Je suis Sinbad, roi de Sindria, aventurier des sept mers ! Merci pour cet accueil chaleureux !", {effect:"bounce"}),
  M("shy", "B-bonjour, Votre Majesté ! Je suis Miqka, la maire. Je… je fais une révérence ? Je ne sais pas faire les révérences."),
  P("sinbad")("neutre", "Pas de révérence entre amis ! Une ville qui a un chef de tribu à deux têtes, un prince bagarreur et un artificier dangereux, c'est une ville qui me plaît."),
  P("sinbad")("neutre", "J'ai fondé mon pays à partir de rien, avec des amis rencontrés en chemin. Je reconnais ce genre d'endroit au premier coup d'œil."),
  M("excited", "Vous aussi, vous avez commencé avec un terrain vague ?!", {effect:"hop"}),
  P("sinbad")("neutre", "Avec une île, un bateau, et beaucoup trop de confiance en moi. Mais c'est un bon début."),
  N("Derrière le roi, un homme en tenue blanche, l'air épuisé, tient une pile de documents encore plus haute que celle de Big Jim.", {left:"sinbad:neutre"}),
  N("Il s'appelle Ja'far, conseiller du roi. Il prévient tout le monde, très sérieusement, de ne surtout pas laisser Sinbad boire avant la signature."),
  M("idea", "Pourquoi ? Il devient méchant ?"),
  P("sinbad")("neutre", "Moi ? Jamais ! Je deviens juste… un peu trop généreux. Et un peu distrait. Ja'far exagère toujours."),
  N("Visite officielle de {ville}. Sinbad serre des mains, complimente tout, et se fait des amis à chaque coin de rue.", {card:"Visite officielle…", bg:"arene", left:"zenos:neutre"}),
  P("zenos")("neutre", "Un roi. Tu as l'air fort. Viens te battre, ce soir, dans l'arène."),
  P("sinbad")("neutre", "Je me bats seulement quand je n'ai pas le choix. Mais je bois volontiers un verre avec un adversaire intéressant.", {left:"sinbad:neutre"}),
  P("zenos")("neutre", "… Tu esquives. Avec élégance. Je reviendrai à la charge.", {left:"zenos:neutre"}),
  N("Au casino, Aventurine propose une partie de dés. Sinbad gagne. Aventurine propose une revanche. Sinbad gagne encore.", {bg:"casino", left:"aventurine:neutre"}),
  P("aventurine")("neutre", "Ta chance est presque insolente. Je ne sais pas si je dois t'admirer ou te faire surveiller par Topaz."),
  P("sinbad")("neutre", "Ce n'est pas de la chance. C'est le destin. Il m'a toujours bien aimé. Un peu trop, parfois.", {left:"sinbad:neutre"}),
  N("Au marché, Bakool Ja Ja offre une brochette au roi. Sinbad la mange d'une bouchée sans même transpirer. Les deux têtes de Bakool sont impressionnées.", {bg:"marche", left:"bakool:neutre"}),
  P("bakool")("neutre", "Ce roi mange comme un vrai chef. Bakool Ja Ja approuve. Une tête approuve beaucoup."),
  N("Le soir, pour fêter l'alliance avant la signature, tout le monde se retrouve au bar. Ja'far a dit non. Tout le monde a fait semblant de ne pas entendre.", {card:"Le soir, au bar…", bg:"bar", left:"homer:joie"}),
  HO("joie", "Un roi au bar ! Je peux lui demander s'il connaît un roi des donuts ?", {effect:"squish"}),
  P("sinbad")("neutre", "Le roi des donuts ? C'est toi, je pense. Tu as la couronne, là, sur le menton.", {left:"sinbad:neutre"}),
  HO("joie", "C'est du sucre glace. Mais j'accepte le titre !", {left:"homer:joie"}),
  N("Une heure passe. Puis trois. Les verres s'accumulent. Sinbad chante, Fandaniel lance des étincelles, Chiaki dort sur le comptoir, et Big Jim fait signer quelque chose à tout le monde.", {trans:"black", left:"fandaniel:neutre"}),
  N("Le lendemain matin. Le soleil se lève sur {ville}. Sur le quai, un roi se réveille, assis dans un tonneau, avec une couronne de fleurs sur la tête.", {card:"Le lendemain matin…", bg:"port", left:"sinbad:neutre"}),
  P("sinbad")("neutre", "… Où suis-je ? Pourquoi je suis dans un tonneau ? Et où sont mes bijoux ?! Mes réceptacles ! Ja'far va me tuer.", {effect:"shake"}),
  M("shy", "Bonjour, Majesté… Vous avez beaucoup chanté. Et vous avez offert vos bijoux. À tout le monde. Un par personne."),
  P("sinbad")("neutre", "Encore ?! Ce n'est pas la première fois. Ni la deuxième. Ja'far tient un registre."),
  N("Commence alors la grande chasse aux bijoux, à travers toute la ville, avant que le conseiller ne se réveille.", {left:"sinbad:neutre"}),
  HK("buste", "Un bracelet royal ? Oh, je l'ai acheté hier soir à un homme très généreux. Je vous le revends ! 15 Kwak Coin ! Et je l'ai déjà revendu deux fois ce matin ^^", {left:"hancock:buste", effect:"squish"}),
  M("pointing", "HANCOCK ! Rends le bracelet au roi !", {effect:"shake"}),
  P("topaz")("neutre", "Numby l'a déjà retrouvé. Dans la poche de Big Jim. Avec un collier. Et un formulaire d'alliance signé de travers.", {left:"topaz:neutre"}),
  BJ("neutre", "Je les gardais en sécurité. Pour le bien du royaume. Des deux royaumes.", {left:"bigjim:neutre"}),
  P("rin")("neutre", "La boucle d'oreille était dans les buts. Il a tiré un penalty avec, cette nuit. Il a raté.", {left:"rin:neutre"}),
  P("chiaki")("neutre", "La bague, c'est moi. Il me l'a donnée comme jeton pour la borne. Elle ne rentre pas dans la fente, je pense.", {left:"chiaki:neutre"}),
  ES("garde", "Et le dernier était sur le toit, accroché au cou du pigeon. Je ne veux pas savoir comment.", {left:"estinien:garde"}),
  N("À midi, tous les bijoux sont rendus. Ja'far se réveille, compte, recompte, et ne trouve rien à redire. Il soupçonne quand même quelque chose.", {left:"sinbad:neutre"}),
  P("sinbad")("neutre", "Miqka. Ta ville m'a sauvé la mise. Une fois de plus, je dois tout à mes amis. Ça, c'est le vrai trésor des sept mers."),
  M("sweet", "C'est normal. Ici, quand quelqu'un se perd, on revient le chercher. Même les rois dans les tonneaux."),
  N("Grande salle du conseil. La signature officielle de l'alliance. Tout {ville} est là, serré entre les deux drapeaux de Big Jim et le troisième, qu'il a ajouté ce matin.", {card:"La signature de l'alliance…", bg:"conseil", left:"sinbad:neutre"}),
  P("sinbad")("neutre", "Par la présente, Sindria et {ville} deviennent alliées. Commerce, amitié, et entraide en cas de tempête. Ou de feux d'artifice."),
  P("fandaniel")("neutre", "J'ai préparé un petit bouquet pour la signature ! Rien de dangereux ! Presque rien !", {left:"fandaniel:neutre"}),
  P("topaz")("neutre", "Le placard « FIN DU MONDE » est toujours fermé. J'ai vérifié deux fois.", {left:"topaz:neutre"}),
  P("sinbad")("neutre", "Et maintenant, une dernière chose. En tant que roi allié, j'ai un petit pouvoir. Un tout petit pouvoir. Celui d'accorder une grâce.", {left:"sinbad:neutre"}),
  M("shy", "Une… grâce ? Pour qui ?"),
  P("sinbad")("neutre", "J'ai entendu parler d'une petite maire qui a passé soixante-sept ans en prison pour un Crousty. Ça m'a semblé un peu… excessif."),
  P("sinbad")("neutre", "Alors, symboliquement, au nom de Sindria et de ses alliés : Miqka, tu es pardonnée. Et le Crousty aussi."),
  N("Un silence. Puis la salle entière éclate en applaudissements. Homer pleure dans un donut. Bakool Ja Ja applaudit avec quatre mains, puisqu'il a deux fois plus d'enthousiasme.", {scr:"flash"}),
  M("excited", "Pardonnée ! Je suis pardonnée ! Même le Crousty ! Surtout le Crousty !", {effect:"jump"}),
  HK("buste", "Je vends des certificats de pardon ! Copies officielles ! 15 Kwak Coin ! Le premier est authentique, le deuxième aussi ^^", {left:"hancock:buste"}),
  P("zenos")("neutre", "Hm. Une ville qui pardonne. Étrange. Mais ses habitants se battent bien. Je reste.", {left:"zenos:neutre"}),
  P("aventurine")("neutre", "Je parie que cette ville va devenir immense. Et pour une fois, je mise tout sans hésiter.", {left:"aventurine:neutre"}),
  BJ("neutre", "Madame la maire. Au nom du conseil… félicitations. Sincèrement. Pour le bien de la ville. Et un peu pour vous.", {left:"bigjim:neutre"}),
  M("sweet", "Merci, Big Jim. Merci à tout le monde. Quand je suis sortie de prison, je n'avais qu'un terrain vague et un pigeon."),
  M("excited", "Maintenant, j'ai une ville. Et une famille un peu bizarre. Et c'est la meilleure du monde !", {effect:"bounce"}),
  P("sinbad")("neutre", "Alors, à {ville} ! À ses habitants ! Et à la prochaine aventure !", {left:"sinbad:neutre"}),
  N("Ce soir-là, Sinbad lève l'ancre sous les feux de Fandaniel. Sur le quai, toute la ville fait signe. Ja'far, à la proue, compte les bijoux une dernière fois.", {card:"Au coucher du soleil, au port…", bg:"port"}),
  N("Et dans la poche de Miqka, il y a une petite lettre royale, un certificat de pardon authentique, et un Crousty. Croustillant dehors. Fondant dedans. Enfin légal.", {right:"sweet"}),
  {end:true}
]};

})();
